<?php require __DIR__.'/includes/bootstrap.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$s=db()->prepare('SELECT id,name,password_hash FROM customers WHERE phone=? OR email=? LIMIT 1');$s->execute([trim($_POST['identity']??''),trim($_POST['identity']??'')]);$u=$s->fetch();if($u&&$u['password_hash']&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['customer_id']=$u['id'];$_SESSION['customer_name']=$u['name'];go('index.php');}$error='بيانات الدخول غير صحيحة.';}?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تسجيل الدخول</title><link rel="stylesheet" href="assets/css/store.css"></head><body><?php include __DIR__.'/includes/nav.php';?><main class="inner login"><h1>تسجيل الدخول</h1><?php if($error):?><p class="notice"><?=h($error)?></p><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>الهاتف أو البريد<input name="identity" required></label><label>كلمة المرور<input type="password" name="password" required></label><button class="gold">دخول</button><p><a href="register.php">إنشاء حساب جديد</a></p></form></main></body></html>